class Solution:

    ''' WITH PRINT AND TEST '''
    def lengthOfLongestSubstring(self, s: str) -> int:
        
        '''
        *OLD version, i cant be bothered to update this.
        restrictions: len_max_substring CANNOT contain duplicates.
        time complexity: O(n^2)
        method: sliding window
        '''

        L = 0
        R = 0
        n = len(s)
        substring = []
        len_max_substring = 0
        all_substrings=[] #temp while testing
        max_substring=""
        while R < n:
            if s[R] not in substring:
                print(f"    add {s[R]} -> {substring}")
                substring.append(s[R])   
                if R == n - 1:
                    all_substrings.append(''.join(substring)) #temp while testing
                    if len(substring) > len_max_substring: 
                        max_substring = "".join(substring)
                        len_max_substring = len(substring)
                R += 1
            else:
                all_substrings.append(''.join(substring)) #temp while testing
                if len(substring) > len_max_substring: 
                    max_substring = "".join(substring)
                    len_max_substring = len(substring) 
                print()
                print(f"    substring: {substring}")
                print(f"    max_substring: {max_substring}")
                print(f"    len_max_substring: {len_max_substring}")
                substring = []
                L += 1
                R = L
        # TESTING answers
        lens = sorted(len(x) for x in all_substrings)
        limit = lens[int(len(lens) * 0.999)] if lens else 0
        all_substrings_adj = [i for i in all_substrings if len(i) >= limit] if len([i for i in all_substrings if len(i) >= limit]) > 30 else [i for i in all_substrings if len(i) >= (lens[int(len(lens) * 0.999)] if lens else 0)]
        print(f"(final) max_substring: {max_substring}")
        print(f"(final) len_max_substring: {len_max_substring}")
        print(f"limit: {limit}")
        print(f"len(all_substrings_adj): {all_substrings_adj}")
        print(f"max: {[len(max(all_substrings, key=len))]} : {max(all_substrings, key=len)}")
        print(f"min: {[len(min(all_substrings))]} : {min(all_substrings)}")
        print(f"\nall substring >= {limit}")
        for i in all_substrings_adj:
            print(f"    {[len(str(i))]} : {i}")
        return len_max_substring

    ''' CLEAN VERSION '''
    def lengthOfLongestSubstring(self, s: str) -> int:
        
        '''
        restrictions: len_max_substring CANNOT contain duplicates.
        time complexity: 
        method: sliding window



    
        '''

        L = 0
        R = L
        n = len(s)
        len_max_substring = 0
        seen = set()
        while R < n:

            if s[R] not in seen:
                seen.add(s[R])
                R += 1

            while s[R] in seen:
                s = s[L:]
                L += 1
                if len(seen) > len_max_substring: len_max_substring = len(seen)
                n -= 1
        return len_max_substring


